<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';
import {api,action} from '../lib/api.js';
const props=defineProps({work:Object});const entry=ref('index.html'),preview=ref(null),frame=ref(null),open=ref(false),target=ref(null),note=ref(''),rows=ref([]),selecting=ref(true),busy=ref(false),width=ref('100%');
const base=id=>`/api/sessions/${id}`;
async function refresh(){const id=props.work.s.session;if(!id)return;const data=await api(base(id)+'/annotations');if(id===props.work.s.session)rows.value=data.annotations;}
watch(()=>[props.work.s.session,props.work.s.localFolder],()=>{preview.value=null;open.value=false;target.value=null;rows.value=[];note.value='';props.work.safe(refresh);},{immediate:true});
async function load(){const id=props.work.s.session;if(!id)throw new Error('请先创建会话并生成页面');const data=await action(base(id)+'/preview',{entry:entry.value});if(id===props.work.s.session){preview.value=data;open.value=true;target.value=null;selecting.value=true;}}
function receive(event){const data=event.data;if(!open.value||event.source!==frame.value?.contentWindow||event.origin!=='null'||data?.token!==preview.value?.token||data.type!=='ecoder:annotation'||data.entry!==preview.value.entry)return;
if(typeof data.selector!=='string'||typeof data.text!=='string')return;
target.value={selector:data.selector.slice(0,2000),text:data.text.slice(0,500),component:String(data.component||'').slice(0,200),source:String(data.source||'').slice(0,500),rect:data.rect,viewport:data.viewport};note.value='';}
window.addEventListener('message',receive);onBeforeUnmount(()=>window.removeEventListener('message',receive));
function mode(){selecting.value=!selecting.value;frame.value?.contentWindow?.postMessage({type:'ecoder:mode',token:preview.value.token,enabled:selecting.value},'*');}
async function save(){if(!target.value)return;const id=props.work.s.session;await action(base(id)+'/annotations',{...target.value,entry:preview.value.entry,revision:preview.value.revision,note:note.value});if(id===props.work.s.session){target.value=null;note.value='';await refresh();}}
async function submit(){const id=props.work.s.session;busy.value=true;try{const result=await action(base(id)+'/annotations/submit',{ids:rows.value.filter(x=>x.status==='pending').map(x=>x.id)});if(id===props.work.s.session){await props.work.openSession(id);open.value=false;props.work.s.tab='timeline';}}finally{busy.value=false;}}
async function state(row,status){await api(base(props.work.s.session)+`/annotations/${row.id}`,{method:'PATCH',body:JSON.stringify({status})});await refresh();}
function generate(){props.work.s.prompt+=(props.work.s.prompt?'\n':'')+'请根据我的需求生成可预览的前端界面。先检查工作区：独立页面生成 index.html；已有 Vue/React 项目沿用结构并构建 dist/index.html。尽可能给关键元素添加 data-component 和 data-source（源码相对路径）以便视觉标注定位。修改和命令仍需审批。';}
</script>
<template><div class="preview-launch"><p class="section-note">生成界面后选择 HTML 入口，点击组件添加修改意见，再提交给 Agent。Vue / React 项目请先构建静态产物。</p><label>预览入口<input v-model="entry" aria-label="预览入口" placeholder="index.html 或 dist/index.html"></label><button class="secondary" @click="work.safe(load)">打开预览与标注</button><button class="quiet" @click="generate">将生成界面的要求加入输入框</button><small>隔离预览支持本地静态资源，不连接外部接口或开发服务器。</small>
<div v-if="open" class="preview-studio" role="dialog" aria-modal="true" aria-label="前端预览与组件标注"><header><div><strong>界面预览</strong><small>{{preview.entry}}</small></div><button class="quiet" @click="work.safe(load)">刷新产物</button><select v-model="width" aria-label="预览宽度"><option value="100%">自适应</option><option value="390px">手机 390</option><option value="768px">平板 768</option></select><button :aria-pressed="selecting" class="secondary" @click="mode">{{selecting?'标注模式':'交互模式'}}</button><button class="quiet" @click="open=false">关闭预览</button></header>
<div class="preview-body"><div class="preview-canvas"><iframe ref="frame" :key="preview.token" :src="preview.url" sandbox="allow-scripts" referrerpolicy="no-referrer" title="隔离的前端预览" :style="{width}"></iframe></div><aside><h3>组件修改意见</h3><p class="hint">标注模式下点击页面元素。选择器定位 DOM，源码提示帮助查找真实组件。</p>
<form v-if="target" @submit.prevent="work.safe(save)"><code>{{target.selector}}</code><p>{{target.text}}</p><small v-if="target.source">源码提示：{{target.source}}</small><label>修改要求<textarea v-model="note" aria-label="组件修改要求" rows="4" required maxlength="4000" placeholder="例如：按钮改为深蓝色，增加左右间距"></textarea></label><button class="secondary" :disabled="!note.trim()">保存标注</button></form>
<p v-else class="hint">点击要调整的按钮、标题或布局区域。</p>
<article v-for="row in rows" :key="row.id"><code>{{row.selector}}</code><p>{{row.note}}</p><small>{{({pending:'待提交',submitted:'已提交',resolved:'已验收',dismissed:'已忽略'})[row.status]}}</small><div v-if="['pending','submitted'].includes(row.status)"><button class="quiet" @click="work.safe(()=>state(row,'resolved'))">标记已验收</button><button class="quiet" @click="work.safe(()=>state(row,'dismissed'))">忽略</button></div></article>
<button class="secondary submit-feedback" :disabled="busy||work.s.running||!rows.some(x=>x.status==='pending')" @click="work.safe(submit)">{{busy?'正在提交…':'提交待处理标注给 Agent'}}</button><p class="hint">将开启本会话新一轮修改，文件和命令仍逐次审批。完成后刷新产物并验收。</p></aside></div></div></div></template>
<style scoped>.preview-launch{display:grid;gap:12px;font-size:13px}.preview-launch input,.preview-launch textarea{display:block;width:100%;box-sizing:border-box;padding:9px;border:1px solid #d8dce4;border-radius:6px;font:inherit}.preview-launch small,.hint{color:#667085;line-height:1.6}.preview-studio{position:fixed;inset:24px;z-index:900;background:#fff;border:1px solid #cbd0df;box-shadow:0 20px 90px #202b4855;display:flex;flex-direction:column;border-radius:12px;overflow:hidden}.preview-studio header{display:flex;align-items:center;gap:16px;padding:14px 20px;border-bottom:1px solid #dddfea}.preview-studio header>div{margin-right:auto;display:grid;gap:3px}.preview-body{display:flex;flex:1;min-height:0}.preview-canvas{flex:1;background:#e9ecf3;padding:20px;overflow:auto;display:flex;justify-content:center}.preview-canvas iframe{border:0;background:white;height:100%;max-width:100%;flex-shrink:0}.preview-body aside{width:310px;max-width:40%;overflow:auto;padding:18px;border-left:1px solid #dddfea}.preview-body h3{margin:0}.preview-body code{display:block;font-size:11px;overflow-wrap:anywhere;color:#4f46a5}.preview-body article{padding:14px 0;border-top:1px solid #dddfea}.preview-body form{display:grid;gap:10px;margin-bottom:18px}.submit-feedback{width:100%}@media(max-width:700px){.preview-studio{inset:4px}.preview-studio header{flex-wrap:wrap;gap:8px}.preview-body{flex-direction:column}.preview-canvas{min-height:280px}.preview-body aside{width:auto;max-width:none;max-height:40%}}</style>
